-- Update the seed function to also insert comments and offers
-- We need to drop and recreate the function with the full body including comments and offers
-- But since the function body is very large, we'll add a second helper function for comments+offers
-- and call it from the main function.

DROP FUNCTION IF EXISTS seed_demo_comments_and_offers();

CREATE OR REPLACE FUNCTION seed_demo_comments_and_offers()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
  -- Comments
  ON CONFLICT (id) DO NOTHING;

  -- Offers (status 'pending' - DB check constraint)
  ON CONFLICT (id) DO NOTHING;
END;
$$;

GRANT EXECUTE ON FUNCTION seed_demo_comments_and_offers() TO authenticated, anon;

-- Now update the main seed function to call the helper
-- We need to recreate it with the helper call at the end
-- Since we can't easily edit the function body, we'll create a wrapper
CREATE OR REPLACE FUNCTION seed_demo_marketplace_data_full()
RETURNS TABLE(action text, count int)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = auth, pg_catalog, public
AS $$
BEGIN
  PERFORM seed_demo_marketplace_data();
  PERFORM seed_demo_comments_and_offers();
  RETURN QUERY SELECT 'seeded'::text, COUNT(*)::int FROM public.artist_profiles WHERE id::text LIKE '22222222-2222-2222-2222-%';
END;
$$;

GRANT EXECUTE ON FUNCTION seed_demo_marketplace_data_full() TO authenticated, anon;