  INSERT INTO commission_comments (id, commission_request_id, author_id, author_name, author_role, author_avatar_url, body, is_public, is_hidden, created_at, updated_at) VALUES
    ('55555555-5555-5555-5555-000000005001', '44444444-4444-4444-4444-000000004001', '11111111-1111-1111-1111-000000000a01', 'Lena Wojcik', 'artist', '/avatar-lena-wojcik.webp', 'Dzien dobry, przy takim formacie dobrze sprawdzilaby sie technika akrylowa z delikatna struktura. Czy zlocenia maja byc bardziej widoczne, czy raczej subtelne i widoczne tylko pod swiatlo?', true, false, '2025-07-16T10:30:00Z', '2025-07-16T10:30:00Z'),
    ('55555555-5555-5555-5555-000000005002', '44444444-4444-4444-4444-000000004001', '11111111-1111-1111-1111-000000000a02', 'Nikodem Halicki', 'artist', 'https://images.pexels.com/photos/18888497/pexels-photo-18888497.jpeg?auto=compress&cs=tinysrgb&w=200', 'W jasnym salonie z duza iloscia swiatla strukturalna tekstura pieknie zagra. Proponuje plotno lniane z widocznym splotem.', true, false, '2025-07-17T09:00:00Z', '2025-07-17T09:00:00Z'),
    ('55555555-5555-5555-5555-000000005003', '44444444-4444-4444-4444-000000004001', '11111111-1111-1111-1111-000000000a09', 'Yuki Nakamura', 'artist', '/avatar-maja-sokolowska.webp', 'Moge zaproponowac organiczne faktury z piaskiem i pigmentem - w tej palecie bezu i bieli daja bardzo spokojny efekt.', true, false, '2025-07-18T11:00:00Z', '2025-07-18T11:00:00Z'),
    ('55555555-5555-5555-5555-000000005004', '44444444-4444-4444-4444-000000004002', '11111111-1111-1111-1111-000000000a06', 'Witold Kruszynski', 'artist', 'https://images.pexels.com/photos/16762319/pexels-photo-16762319.jpeg?auto=compress&cs=tinysrgb&w=200', 'Mam doswiadczenie z projektami deweloperskimi - moge dostarczyc render 3D przed realizacja. Czy paleta jest ostateczna?', true, false, '2025-07-19T10:00:00Z', '2025-07-19T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005005', '44444444-4444-4444-4444-000000004002', '11111111-1111-1111-1111-000000000a08', 'Gustaw Linke', 'artist', 'https://images.pexels.com/photos/18888497/pexels-photo-18888497.jpeg?auto=compress&cs=tinysrgb&w=200', 'W tej palecie graphite/taupe/muted gold sprawdzi sie geometria z precyzyjnymi krawedziami.', true, false, '2025-07-20T14:00:00Z', '2025-07-20T14:00:00Z'),
    ('55555555-5555-5555-5555-000000005006', '44444444-4444-4444-4444-000000004003', '11111111-1111-1111-1111-000000000a06', 'Witold Kruszynski', 'artist', 'https://images.pexels.com/photos/16762319/pexels-photo-16762319.jpeg?auto=compress&cs=tinysrgb&w=200', 'Seria 3 obrazow do lobby to moj profil. Proponuje spojna kolekcje z akcentami zlota. Wernis UV-odporny wliczony.', true, false, '2025-07-11T09:00:00Z', '2025-07-11T09:00:00Z'),
    ('55555555-5555-5555-5555-000000005007', '44444444-4444-4444-4444-000000004003', '11111111-1111-1111-1111-000000000a01', 'Lena Wojcik', 'artist', '/avatar-lena-wojcik.webp', 'W hotelowym oswietleniu UV-odporny wernis to koniecznosc. Czy seria ma miec wspolny motyw, czy trzy spojne ale rozne kompozycje?', true, false, '2025-07-12T11:00:00Z', '2025-07-12T11:00:00Z'),
    ('55555555-5555-5555-5555-000000005008', '44444444-4444-4444-4444-000000004003', '11111111-1111-1111-1111-000000000a03', 'Irena Falska', 'artist', 'https://images.pexels.com/photos/8036832/pexels-photo-8036832.jpeg?auto=compress&cs=tinysrgb&w=200', 'W gorskim hotelu pieknie zagrably pejzaze abstrakcyjne - mgliste formy nawiwiazujace do krajobrazu.', true, false, '2025-07-14T08:00:00Z', '2025-07-14T08:00:00Z'),
    ('55555555-5555-5555-5555-000000005009', '44444444-4444-4444-4444-000000004003', '11111111-1111-1111-1111-000000000a02', 'Nikodem Halicki', 'artist', 'https://images.pexels.com/photos/18888497/pexels-photo-18888497.jpeg?auto=compress&cs=tinysrgb&w=200', 'Wielki format 100x140 w palecie stone/sand - moge zrealizowac w technice akryl + pigment na lnianym plotnie.', true, false, '2025-07-15T13:00:00Z', '2025-07-15T13:00:00Z'),
    ('55555555-5555-5555-5555-000000005010', '44444444-4444-4444-4444-000000004004', '11111111-1111-1111-1111-000000000a07', 'Maja Sokolowska', 'artist', '/avatar-maja-sokolowska.webp', 'Sypialnia w pudrowym rozu i bezach to moj klimat. Proponuje miekkie przejscia w akwareli i akrylu z delikatna tekstura.', true, false, '2025-07-23T10:00:00Z', '2025-07-23T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005011', '44444444-4444-4444-4444-000000004004', '11111111-1111-1111-1111-000000000a09', 'Yuki Nakamura', 'artist', '/avatar-maja-sokolowska.webp', 'Wabi-sabi w tej palecie da bardzo spokojny, medytacyjny efekt. Organiczne faktury, miekkie krawedzie.', true, false, '2025-07-24T09:00:00Z', '2025-07-24T09:00:00Z'),
    ('55555555-5555-5555-5555-000000005012', '44444444-4444-4444-4444-000000004005', '11111111-1111-1111-1111-000000000a08', 'Gustaw Linke', 'artist', 'https://images.pexels.com/photos/18888497/pexels-photo-18888497.jpeg?auto=compress&cs=tinysrgb&w=200', 'Kancelaria i geometria to idealne polaczenie. Proponuje kompozycje w duchu Soulages w palecie grafit/czern/biel/zloto.', true, false, '2025-07-26T10:00:00Z', '2025-07-26T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005013', '44444444-4444-4444-4444-000000004005', '11111111-1111-1111-1111-000000000a02', 'Nikodem Halicki', 'artist', 'https://images.pexels.com/photos/18888497/pexels-photo-18888497.jpeg?auto=compress&cs=tinysrgb&w=200', 'Minimalizm w tej palecie zadziala bardzo elegancko. Monochromatyczna kompozycja z akcentem zlota.', true, false, '2025-07-27T11:00:00Z', '2025-07-27T11:00:00Z'),
    ('55555555-5555-5555-5555-000000005014', '44444444-4444-4444-4444-000000004006', '11111111-1111-1111-1111-000000000a05', 'Honorata Czech', 'artist', 'https://images.pexels.com/photos/6816588/pexels-photo-6816588.jpeg?auto=compress&cs=tinysrgb&w=200', 'Obraz na prezent slubny to piekny projekt. Moge stworzyc symboliczna kompozycje z personalizacja.', true, false, '2025-07-29T10:00:00Z', '2025-07-29T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005015', '44444444-4444-4444-4444-000000004006', '11111111-1111-1111-1111-000000000a01', 'Lena Wojcik', 'artist', '/avatar-lena-wojcik.webp', 'Zlocenia jako symbol jednosci - subtelne, widoczne pod swiatlo. Moge zaproponowac kompozycje z delikatna struktura.', true, false, '2025-07-30T09:00:00Z', '2025-07-30T09:00:00Z'),
    ('55555555-5555-5555-5555-000000005016', '44444444-4444-4444-4444-000000004007', '11111111-1111-1111-1111-000000000a04', 'Oskar Renski', 'artist', 'https://images.pexels.com/photos/18888491/pexels-photo-18888491.jpeg?auto=compress&cs=tinysrgb&w=200', 'Terracotta i black accents - dynamiczna paleta. Moge zaproponowac ekspresyjna kompozycje z akcentami czerni.', true, false, '2025-07-31T10:00:00Z', '2025-07-31T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005017', '44444444-4444-4444-4444-000000004007', '11111111-1111-1111-1111-000000000a01', 'Lena Wojcik', 'artist', '/avatar-lena-wojcik.webp', 'Pracuje z architektami - moge dopasowac kompozycje do moodboardu. Probka kolorystyczna do akceptacji.', true, false, '2025-08-01T11:00:00Z', '2025-08-01T11:00:00Z'),
    ('55555555-5555-5555-5555-000000005018', '44444444-4444-4444-4444-000000004008', '11111111-1111-1111-1111-000000000a09', 'Yuki Nakamura', 'artist', '/avatar-maja-sokolowska.webp', 'Organiczne faktury w palecie gliny i karmelu - to moj jezyk. Piasek, pigment, struktura.', true, false, '2025-08-02T10:00:00Z', '2025-08-02T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005019', '44444444-4444-4444-4444-000000004008', '11111111-1111-1111-1111-000000000a01', 'Lena Wojcik', 'artist', '/avatar-lena-wojcik.webp', 'Struktura z pasta strukturalna w tonach karmelu i ciemnego brazu - relief dotykalny, wernis matowy.', true, false, '2025-08-03T09:00:00Z', '2025-08-03T09:00:00Z'),
    ('55555555-5555-5555-5555-000000005020', '44444444-4444-4444-4444-000000004009', '11111111-1111-1111-1111-000000000a09', 'Yuki Nakamura', 'artist', '/avatar-maja-sokolowska.webp', 'Gabinet terapeutyczny i wabi-sabi to idealne polaczenie. Organiczne faktury w off-white i sage.', true, false, '2025-08-04T10:00:00Z', '2025-08-04T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005021', '44444444-4444-4444-4444-000000004009', '11111111-1111-1111-1111-000000000a02', 'Nikodem Halicki', 'artist', 'https://images.pexels.com/photos/18888497/pexels-photo-18888497.jpeg?auto=compress&cs=tinysrgb&w=200', 'Minimalizm w grey beige i sage - bardzo spokojna kompozycja. Organiczne formy, miekkie krawedzie.', true, false, '2025-08-05T09:00:00Z', '2025-08-05T09:00:00Z'),
    ('55555555-5555-5555-5555-000000005022', '44444444-4444-4444-4444-000000004010', '11111111-1111-1111-1111-000000000a04', 'Oskar Renski', 'artist', 'https://images.pexels.com/photos/18888491/pexels-photo-18888491.jpeg?auto=compress&cs=tinysrgb&w=200', 'Loft industrialny i wyrazista abstrakcja - to moj teren. Czern, biel, kobalt, rdza w dynamicznej kompozycji.', true, false, '2025-08-06T10:00:00Z', '2025-08-06T10:00:00Z'),
    ('55555555-5555-5555-5555-000000005023', '44444444-4444-4444-4444-000000004010', '11111111-1111-1111-1111-000000000a10', 'Brunon Dracz', 'artist', 'https://images.pexels.com/photos/18888491/pexels-photo-18888491.jpeg?auto=compress&cs=tinysrgb&w=200', 'W lofcie z betonem swietnie zagra narracyjna abstrakcja z symbolika - warstwy, rdza, slady.', true, false, '2025-08-07T09:00:00Z', '2025-08-07T09:00:00Z')
